    sh::State state;sh::Facts facts;std::unique_ptr<RefreshService> refresh;std::unique_ptr<AddressService> addresses;std::unique_ptr<a::RecoverySession> recovery;std::filesystem::path scratch;std::vector<a::Request> effects;bool refresh_now{},lock{},ready{},locked{};int calls{};
